; ============================================================================
; Tomb Raider (UE) (M5) [C][!].gbc  -  the game's own PCM player (not GHX code)
;
; Tomb Raider plays its digital sounds outside the GHX engine. The in-game music
; build (bank $7E, ghx_tombraider_bank7E_v00218.asm) starts every level with
; SFX 29, which silences channel 3 and locks it for the sound effects (time $FF);
; the routines below then stream 4-bit PCM into wave RAM from the LCD (LYC)
; interrupt. The 9 samples are in banks $F8-$FA and are included as data.
;
; Assemble: rgbasm -o x.o ghx_tombraider_bank0_pcm.asm ; rgblink -o x.gb x.o
; (the sections are placed at their original addresses; everything else in
; x.gb is padding)
; ============================================================================

INCLUDE "ghx_hw.inc"

DEF wPCM_Buffer            EQU $C040
DEF wPCM_State             EQU $C080
DEF wPCM_Bank              EQU $C081
DEF wPCM_PtrLo             EQU $C082
DEF wPCM_PtrHi             EQU $C083
DEF wPCM_CountLo           EQU $C084
DEF wPCM_CountHi           EQU $C085
DEF wPCM_IRQIndex          EQU $C086
DEF wLCDCShadow            EQU $C08F
DEF wC192                  EQU $C192
DEF LYC_Handler_Line135    EQU $03BE   ; rest of the game's LYC handler

SECTION "TR LYC handler (PCM part)", ROM0[$0398]

;; Part of the game's LCD STAT (LY=LYC) interrupt. It runs four times per frame
;; (LYC = $14, $3B, $61, $87 from LYC_Lines) and pushes one 16-byte block of the
;; current PCM buffer into wave RAM each time. On the first line of the frame
;; ($14) it also refills the 64-byte buffer from ROM (jp PCM_FillBuffer).
LYC_Handler:
    ldh a, [rLY]                ; 0398
    cp $87                      ; 039A
    call z, LYC_Handler_Line135 ; 039C  line $87: game code (not PCM related)
    call PCM_WriteWaveRAM       ; 039F  16 bytes -> wave RAM
    ld hl, wPCM_IRQIndex        ; 03A2
    inc [hl]                    ; 03A5
    ld a, [hl]                  ; 03A6
    and $03                     ; 03A7
    add a,$BA                   ; 03A9
    ld l, a                     ; 03AB
    ld a, $03                   ; 03AC
    adc a,$00                   ; 03AE
    ld h, a                     ; 03B0
    ld a, [hl]                  ; 03B1
    ldh [rLYC], a               ; 03B2
    cp $14                      ; 03B4
    ret nz                      ; 03B6
    jp PCM_FillBuffer           ; 03B7

;; LYC values of the four PCM refills per frame
LYC_Lines:
    db $14, $3B, $61, $87                       ; 03BA 

SECTION "TR PCM player", ROM0[$0682]

;; Called by the game before the GHX engine is (re)started: APU on, wave
;; channel prepared for PCM (NR33 = $F0 -> wave frequency $6F0 = 7710 Hz) and
;; the PCM player stopped.
PCM_InitAPU:
    ld a, $84                   ; 0682
    ldh [rNR52], a              ; 0684
    xor a                       ; 0686
    ldh [rNR30], a              ; 0687
    ldh [rNR51], a              ; 0689
    ld a, $77                   ; 068B
    ldh [rNR50], a              ; 068D
    ld a, $FF                   ; 068F
    ldh [rNR51], a              ; 0691
    ld a, $80                   ; 0693
    ldh [rNR31], a              ; 0695
    ld a, $20                   ; 0697
    ldh [rNR32], a              ; 0699
    ld a, $F0                   ; 069B
    ldh [rNR33], a              ; 069D
    xor a                       ; 069F
    ld [wPCM_State], a          ; 06A0
    ret                         ; 06A3

;; PCM_Play: A = sample number (0-8), called from bank $0C ($7A5F/$7A69).
;; Entry = [bank] [dw address] [dw length]; the length counts 64-byte chunks.
PCM_Play:
    ld l, a                     ; 06A4
    add a,a                     ; 06A5
    add a,a                     ; 06A6
    add a,l                     ; 06A7
    ld l, a                     ; 06A8
    ld h, $00                   ; 06A9
    ld bc, PCM_SampleTable      ; 06AB
    add hl, bc                  ; 06AE
    ld a, [hl+]                 ; 06AF
    ld c, [hl]                  ; 06B0
    inc hl                      ; 06B1
    ld b, [hl]                  ; 06B2
    inc hl                      ; 06B3
    ld e, [hl]                  ; 06B4
    inc hl                      ; 06B5
    ld d, [hl]                  ; 06B6
    jp PCM_Start                ; 06B7
PCM_SampleTable:
    db BANK(TRPCM0)
    dw TRPCM0
    dw 57                                        ; 06BA sample 0: 57 x 64 bytes
    db BANK(TRPCM1)
    dw TRPCM1
    dw 30                                        ; 06BF sample 1: 30 x 64 bytes
    db BANK(TRPCM2)
    dw TRPCM2
    dw 139                                       ; 06C4 sample 2: 139 x 64 bytes
    db BANK(TRPCM3)
    dw TRPCM3
    dw 118                                       ; 06C9 sample 3: 118 x 64 bytes
    db BANK(TRPCM4)
    dw TRPCM4
    dw 47                                        ; 06CE sample 4: 47 x 64 bytes
    db BANK(TRPCM5)
    dw TRPCM5
    dw 30                                        ; 06D3 sample 5: 30 x 64 bytes
    db BANK(TRPCM6)
    dw TRPCM6
    dw 12                                        ; 06D8 sample 6: 12 x 64 bytes
    db BANK(TRPCM7)
    dw TRPCM7
    dw 16                                        ; 06DD sample 7: 16 x 64 bytes
    db BANK(TRPCM8)
    dw TRPCM8
    dw 18                                        ; 06E2 sample 8: 18 x 64 bytes

;; A = bank, BC = address, DE = length: arm the player (wPCM_State bit 0).
;; The count is stored +1 and checked after each copy, so exactly "length"
;; chunks are heard (the chunk copied last is dropped when the channel stops).
PCM_Start:
    ld hl, wPCM_State           ; 06E7
    set 1, [hl]                 ; 06EA
    push hl                     ; 06EC
    inc hl                      ; 06ED
    ld [hl+], a                 ; 06EE
    ld [hl], c                  ; 06EF
    inc hl                      ; 06F0
    ld [hl], b                  ; 06F1
    inc hl                      ; 06F2
    inc d                       ; 06F3
    inc e                       ; 06F4
    ld [hl], e                  ; 06F5
    inc hl                      ; 06F6
    ld [hl], d                  ; 06F7
    pop hl                      ; 06F8
    set 0, [hl]                 ; 06F9
    res 1, [hl]                 ; 06FB
    ret                         ; 06FD

;; Once per frame (first LYC line): copy the next 64 bytes of the sample into
;; wPCM_Buffer ($C040-$C07F), following the sample into the next bank at $8000.
;; Wave channel off when the sample is finished.
PCM_FillBuffer:
    ld hl, wPCM_State           ; 06FE
    ld a, [hl+]                 ; 0701
    xor $01                     ; 0702
    jr nz, PCM_FillBuffer_Off   ; 0704
    ld a, [hl+]                 ; 0706
    rst $00                     ; 0707
    push af                     ; 0708
    ld a, [hl+]                 ; 0709
    ld h, [hl]                  ; 070A
    ld l, a                     ; 070B
    ld de, wPCM_Buffer          ; 070C
    ld c, $08                   ; 070F
PCM_FillBuffer_Loop:
    ld a, [hl+]                 ; 0711
    ld [de], a                  ; 0712
    inc e                       ; 0713
    ld a, [hl+]                 ; 0714
    ld [de], a                  ; 0715
    inc e                       ; 0716
    ld a, [hl+]                 ; 0717
    ld [de], a                  ; 0718
    inc e                       ; 0719
    ld a, [hl+]                 ; 071A
    ld [de], a                  ; 071B
    inc e                       ; 071C
    ld a, [hl+]                 ; 071D
    ld [de], a                  ; 071E
    inc e                       ; 071F
    ld a, [hl+]                 ; 0720
    ld [de], a                  ; 0721
    inc e                       ; 0722
    ld a, [hl+]                 ; 0723
    ld [de], a                  ; 0724
    inc e                       ; 0725
    ld a, [hl+]                 ; 0726
    ld [de], a                  ; 0727
    inc e                       ; 0728
    dec c                       ; 0729
    jr nz, PCM_FillBuffer_Loop  ; 072A
    ld a, l                     ; 072C
    ld b, h                     ; 072D
    ld hl, wPCM_Bank            ; 072E
    bit 7, b                    ; 0731
    jr z, PCM_FillBuffer_NoCross; 0733
    inc [hl]                    ; 0735
    ld b, $40                   ; 0736
PCM_FillBuffer_NoCross:
    inc hl                      ; 0738
    ld [hl+], a                 ; 0739
    ld [hl], b                  ; 073A
    ld hl, wPCM_CountLo         ; 073B
    dec [hl]                    ; 073E
    jr nz, PCM_FillBuffer_Done  ; 073F
    inc hl                      ; 0741
    dec [hl]                    ; 0742
    jr nz, PCM_FillBuffer_Done  ; 0743
    ld hl, wPCM_State           ; 0745
    res 0, [hl]                 ; 0748
    xor a                       ; 074A
    ldh [rNR30], a              ; 074B
PCM_FillBuffer_Done:
    pop af                      ; 074D
    rst $00                     ; 074E
    ret                         ; 074F
PCM_FillBuffer_Off:
    xor a                       ; 0750
    ldh [rNR30], a              ; 0751
    ret                         ; 0753

;; Four times per frame: wave channel off, 16 bytes (32 4-bit samples) of
;; wPCM_Buffer -> $FF30-$FF3F, channel on, retrigger (NR34 = $86). 4 x 32 samples
;; per frame = 7646 Hz, played back at 7710 Hz.
PCM_WriteWaveRAM:
    ld hl, wPCM_State           ; 0754
    bit 0, [hl]                 ; 0757
    jr z, PCM_WriteWaveRAM_End  ; 0759
    ld a, [wPCM_IRQIndex]       ; 075B
    dec a                       ; 075E
    and $03                     ; 075F
    swap a                      ; 0761
    and $F0                     ; 0763
    add a,$40                   ; 0765
    ld l, a                     ; 0767
    ld a, $00                   ; 0768
    adc a,$C0                   ; 076A
    ld h, a                     ; 076C
    ld de, rNR30                ; 076D
    ld c, $30                   ; 0770
    xor a                       ; 0772
    ld [de], a                  ; 0773
    ld a, [hl+]                 ; 0774
    ldh [c], a                  ; 0775
    inc c                       ; 0776
    ld a, [hl+]                 ; 0777
    ldh [c], a                  ; 0778
    inc c                       ; 0779
    ld a, [hl+]                 ; 077A
    ldh [c], a                  ; 077B
    inc c                       ; 077C
    ld a, [hl+]                 ; 077D
    ldh [c], a                  ; 077E
    inc c                       ; 077F
    ld a, [hl+]                 ; 0780
    ldh [c], a                  ; 0781
    inc c                       ; 0782
    ld a, [hl+]                 ; 0783
    ldh [c], a                  ; 0784
    inc c                       ; 0785
    ld a, [hl+]                 ; 0786
    ldh [c], a                  ; 0787
    inc c                       ; 0788
    ld a, [hl+]                 ; 0789
    ldh [c], a                  ; 078A
    inc c                       ; 078B
    ld a, [hl+]                 ; 078C
    ldh [c], a                  ; 078D
    inc c                       ; 078E
    ld a, [hl+]                 ; 078F
    ldh [c], a                  ; 0790
    inc c                       ; 0791
    ld a, [hl+]                 ; 0792
    ldh [c], a                  ; 0793
    inc c                       ; 0794
    ld a, [hl+]                 ; 0795
    ldh [c], a                  ; 0796
    inc c                       ; 0797
    ld a, [hl+]                 ; 0798
    ldh [c], a                  ; 0799
    inc c                       ; 079A
    ld a, [hl+]                 ; 079B
    ldh [c], a                  ; 079C
    inc c                       ; 079D
    ld a, [hl+]                 ; 079E
    ldh [c], a                  ; 079F
    inc c                       ; 07A0
    ld a, [hl+]                 ; 07A1
    ldh [c], a                  ; 07A2
    ld a, $80                   ; 07A3
    ld [de], a                  ; 07A5
    ld a, $86                   ; 07A6
    ldh [rNR34], a              ; 07A8
PCM_WriteWaveRAM_End:
    ret                         ; 07AA

; ============================================================================
SECTION "TR PCM samples bank $F8", ROMX[$4000], BANK[$F8]
; ============================================================================

